//! The Ubuntu packages the Linux roots are assembled from (LINUX_ROOTS,
//! DEBS_ARM64). CI's package cache is keyed on this file, so a branch
//! that changes no package reuses it (WORKFLOW "CI build caches").

/// A Linux root file system assembled from a distribution's packages
/// (ROADMAP LD): the files a program's libraries and data need, each at
/// its path in the package, unpacked on first use into
/// `target/prebuilt/<name>/` (a module path `target/prebuilt/<name>/usr/`
/// ships that tree as `/usr`). Not in the repository; THIRD_PARTY.md
/// lists them.
pub struct LinuxRoot {
    pub name: &'static str,
    pub debs: &'static [Deb],
}

/// A Debian package of Ubuntu 24.04 (noble), its release pocket's
/// version (never changed once released; the pool keeps it).
pub struct Deb {
    /// Its path under archive.ubuntu.com/ubuntu/pool/.
    pub pool: &'static str,
    /// From the release's signed `Packages` index
    /// (dists/noble/<component>/binary-amd64/Packages.xz, whose hash is in
    /// the signed InRelease).
    pub sha256: &'static str,
    /// The files used, by their paths in the package; each lands at the
    /// same path in the root. A symbolic link (a library's soname) is its
    /// target's bytes under the link's path: boot modules carry no links.
    /// `<installed>=<in the package>` is a file its maintainer script
    /// installs under another name with update-alternatives (libblas3's
    /// `usr/lib/x86_64-linux-gnu/libblas.so.3`, a link through
    /// /etc/alternatives to `blas/libblas.so.3`): the package's file at
    /// the installed path, which is the one a minimal install has. A path
    /// ending in `/` is a directory of the package, made empty: one a
    /// program looks for with nothing used beneath it (GIMP's plug-ins
    /// check that `usr/share/locale/` is there).
    pub files: &'static [&'static str],
}

/// The arm64 builds of LINUX_ROOTS' packages, for the aarch64 twins of
/// their scenarios: each amd64 package's pool path and the SHA-256 of the
/// arm64 package of the same version (`_arm64.deb`, on ports.ubuntu.com),
/// from the release's signed arm64 Packages index (dists/resolute/
/// <component>/binary-arm64/Packages.xz, its hash in the signed
/// InRelease). Architecture-independent packages (`_all.deb`) are the
/// same file on both. A root built for arm64 (`<name>-arm64`) has its
/// files at the multiarch path `aarch64-linux-gnu` instead of
/// `x86_64-linux-gnu`.
